<?php if ( ! defined( 'ABSPATH' ) ) { exit; } $cards=get_option('nvconsult_v2_journey_cards',array()); if(empty($cards)||!is_array($cards)){$cards=array(array('title'=>__( 'I Want to Study Abroad', 'nvconsult-theme-v2' ),'subtitle'=>__( 'Academic pathways', 'nvconsult-theme-v2' ),'description'=>__( 'Find countries, schools, and programs tailored to your goals.', 'nvconsult-theme-v2' ),'image_url'=>'','btn_label'=>__( 'Explore Study Options', 'nvconsult-theme-v2' ),'btn_link'=>'#','color'=>'blue','enabled'=>true,'order'=>1),array('title'=>__( 'I Want to Work Abroad', 'nvconsult-theme-v2' ),'subtitle'=>__( 'Career pathways', 'nvconsult-theme-v2' ),'description'=>__( 'Browse international roles and relocation support opportunities.', 'nvconsult-theme-v2' ),'image_url'=>'','btn_label'=>__( 'View Work Opportunities', 'nvconsult-theme-v2' ),'btn_link'=>'#','color'=>'orange','enabled'=>true,'order'=>2)); } usort($cards,static function($a,$b){return (int)$a['order'] <=>(int)$b['order'];}); ?>
<section class="section"><div class="section-inner"><?php nvconsultv2_render_section_heading( 'journey-cards', __( 'What brings you here today?', 'nvconsult-theme-v2' ), '' ); ?><div class="journey-cards-grid"><?php foreach($cards as $card): if(empty($card['enabled'])){continue;} ?><article class="journey-card journey-card--<?php echo esc_attr( 'orange' === $card['color'] ? 'orange' : 'blue' ); ?>"><?php if(!empty($card['image_url'])): ?><div class="journey-card__media"><img src="<?php echo esc_url( $card['image_url'] ); ?>" alt="<?php echo esc_attr( $card['title'] ); ?>"></div><?php endif; ?><p class="badge"><?php echo esc_html( $card['subtitle'] ); ?></p><h3><?php echo esc_html( $card['title'] ); ?></h3><p><?php echo esc_html( $card['description'] ); ?></p><a class="<?php echo esc_attr( nvconsultv2_button_class( $card['color'] ) ); ?>" href="<?php echo esc_url( $card['btn_link'] ); ?>"><?php echo esc_html( $card['btn_label'] ); ?></a></article><?php endforeach; ?></div></div></section>
